/* MODAL */


function escapeHTML(value = "") {
  return String(value).replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  }[char]));
}

function renderSimpleList(items = []) {
  if (!items.length) return "<p>-</p>";
  return `<ul>${items.map(item => `<li>${escapeHTML(item)}</li>`).join("")}</ul>`;
}

function renderFacilityGroups(groups = []) {
  if (!groups.length) return "<p>-</p>";
  return groups.map(group => `
    <div class="detail-group">
      <span class="detail-group-title">${escapeHTML(group.title)}</span>
      ${renderSimpleList(group.items)}
    </div>
  `).join("");
}

function renderTransport(items = []) {
  if (!items.length) return "<p>-</p>";
  return items.map(item => `
    <article class="transport-card">
      <h4>${escapeHTML(item.audience)}</h4>
      <p><strong>Rekomendasi Utama:</strong> ${escapeHTML(item.recommendation)}</p>
      <p><strong>Alasan:</strong> ${escapeHTML(item.justification)}</p>
      <p><strong>Detail Operasional:</strong> ${escapeHTML(item.operational)}</p>
    </article>
  `).join("");
}

function openModal(id) {
  const place = destinations[id];
  if (!place) return;

  const image = document.getElementById("m-img");
  image.src = place.image;
  image.alt = place.name;

  document.getElementById("m-category").textContent = place.categoryLabel;
  document.getElementById("m-title").textContent = place.name;
  document.getElementById("m-desc").textContent = place.description;
  document.getElementById("m-rating").textContent = place.rating;
  document.getElementById("m-distance").textContent = place.distance;
  document.getElementById("m-weather").textContent = place.weather;
  document.getElementById("m-price").textContent = place.price;
  document.getElementById("m-hours").textContent = place.hours;
  document.getElementById("m-area").textContent = place.area;
  document.getElementById("m-maps").href = place.maps;
  document.getElementById("m-video").href = place.youtube || "#";
  document.getElementById("m-location").textContent = place.location || "-";
  document.getElementById("m-attraction").textContent = place.attraction || "-";
  document.getElementById("m-facilities").innerHTML = renderFacilityGroups(place.facilityGroups || []);

  const menuSection = document.getElementById("m-menu-section");
  if (place.menu && place.menu.length) {
    document.getElementById("m-menu").innerHTML = renderFacilityGroups(place.menu);
    document.getElementById("m-menu-note").textContent = place.menuNote || "";
    menuSection.style.display = "";
  } else {
    menuSection.style.display = "none";
  }

  document.getElementById("m-access").textContent = place.access || "-";
  document.getElementById("m-ticket-details").innerHTML = renderSimpleList(place.ticketDetails || []);
  document.getElementById("m-advantage").textContent = place.advantage || "-";
  document.getElementById("m-distance-details").innerHTML = renderSimpleList(place.distanceDetails || []);
  document.getElementById("m-cost-details").textContent = place.costEstimate || "-";
  document.getElementById("m-transport").innerHTML = renderTransport(place.transport || []);

  modal.classList.add("active");
  modal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
}

function closeModal() {
  modal.classList.remove("active");
  modal.setAttribute("aria-hidden", "true");
  document.body.style.overflow = "";
}

window.openDestinationFromMap = function(id) {
  malangMap.closePopup();
  openModal(id);
};

document.querySelectorAll("[data-open-detail]").forEach(button => {
  button.addEventListener("click", event => {
    event.stopPropagation();
    openModal(button.dataset.openDetail);
  });
});

modalCloseBtn.addEventListener("click", closeModal);

modal.addEventListener("click", event => {
  if (event.target === modal) {
    closeModal();
  }
});

document.addEventListener("keydown", event => {
  if (event.key === "Escape" && modal.classList.contains("active")) {
    closeModal();
  }
});

/* KEMBALI KE PETA */

backToMapBtn.addEventListener("click", () => {
  closeModal();

  setTimeout(() => {
    document.getElementById("peta").scrollIntoView({
      behavior: "smooth",
      block: "start"
    });

    setTimeout(() => {
      malangMap.invalidateSize(true);
    }, 450);
  }, 100);
});

/* SEARCH + FILTER */

let activeCategory = "all";

function normalizeText(text) {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function syncTabs() {
  categoryTabs.forEach(tab => {
    tab.classList.toggle(
      "active",
      tab.dataset.category === activeCategory
    );
  });
}


function animateCurrentSelection() {
  const grid = document.getElementById("destinationGrid");
  if (!grid) return;

  grid.classList.remove("grid-switch");
  void grid.offsetWidth;
  grid.classList.add("grid-switch");

  const visibleCards = destinationCards.filter(
    card => !card.classList.contains("hidden")
  );

  visibleCards.forEach((card, index) => {
    card.classList.remove("filter-enter");
    card.style.animationDelay = `${Math.min(index * 45, 260)}ms`;
    void card.offsetWidth;
    card.classList.add("filter-enter");
  });
}

function popControl(element, className) {
  if (!element) return;
  element.classList.remove(className);
  void element.offsetWidth;
  element.classList.add(className);
}

function applyFilters({ scrollToResults = false } = {}) {
  const query = normalizeText(searchInput.value);
  activeCategory = searchCategory.value;

  let visibleCount = 0;

  destinationCards.forEach(card => {
    const cardCategory = card.dataset.category;
    const searchText = normalizeText(
      `${card.dataset.search || ""} ${card.textContent}`
    );

    const categoryMatch =
      activeCategory === "all" ||
      cardCategory === activeCategory;

    const searchMatch =
      query === "" ||
      searchText.includes(query);

    const visible = categoryMatch && searchMatch;

    card.classList.toggle("hidden", !visible);

    if (visible) visibleCount += 1;
  });

  emptyState.classList.toggle("show", visibleCount === 0);

  resultInfo.textContent =
    visibleCount === destinationCards.length &&
    query === "" &&
    activeCategory === "all"
      ? "Menampilkan 9 destinasi pilihan."
      : `${visibleCount} destinasi sesuai pencarian/filter.`;

  syncTabs();
  animateCurrentSelection();

  if (scrollToResults) {
    document.getElementById("destinasi").scrollIntoView({
      behavior: "smooth",
      block: "start"
    });
  }
}

categoryTabs.forEach(tab => {
  tab.addEventListener("click", () => {
    popControl(tab, "choice-pop");
    activeCategory = tab.dataset.category;
    searchCategory.value = activeCategory;
    applyFilters({ scrollToResults: true });
  });
});

searchButton.addEventListener("click", () => {
  popControl(searchButton, "click-pop");
  applyFilters({ scrollToResults: true });
});

searchInput.addEventListener("keydown", event => {
  if (event.key === "Enter") {
    applyFilters({ scrollToResults: true });
  }
});

searchCategory.addEventListener("change", () => {
  const selectedTab = categoryTabs.find(tab => tab.dataset.category === searchCategory.value);
  popControl(selectedTab, "choice-pop");
  applyFilters();
});

let searchTimer;

searchInput.addEventListener("input", () => {
  clearTimeout(searchTimer);

  searchTimer = setTimeout(() => {
    applyFilters();
  }, 170);
});

resetFilterBtn.addEventListener("click", () => {
  searchInput.value = "";
  searchCategory.value = "all";
  activeCategory = "all";
  applyFilters({ scrollToResults: true });
});

/* CARD DOUBLE CLICK -> MAP MARKER */

destinationCards.forEach(card => {
  card.addEventListener("dblclick", () => {
    const id = card.dataset.destinationId;
    const place = destinations[id];

    if (!place) return;

    document.getElementById("peta").scrollIntoView({
      behavior: "smooth",
      block: "start"
    });

    setTimeout(() => {
      malangMap.invalidateSize(true);
      malangMap.setView([place.lat, place.lng], 13, { animate: true });
      destinationMarkers[id].openPopup();
    }, 550);
  });
});

/* REVEAL */

const revealSelectors = [
  ".map-section-head",
  ".map-frame",
  ".category-heading",
  ".category-tabs",
  ".destinations-head",
  ".destination-grid",
  ".about-section"
];

revealSelectors.forEach(selector => {
  document.querySelectorAll(selector).forEach(element => {
    element.classList.add("reveal");
  });
});

const revealObserver = new IntersectionObserver(
  entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add("visible");
        revealObserver.unobserve(entry.target);
      }
    });
  },
  {
    threshold: 0.1,
    rootMargin: "0px 0px -40px 0px"
  }
);

document.querySelectorAll(".reveal").forEach(element => {
  revealObserver.observe(element);
});

/* HERO PARALLAX RINGAN */

const heroImage = document.querySelector(".hero-image");

window.addEventListener("scroll", () => {
  if (window.innerWidth < 820) return;

  const offset = window.scrollY;

  if (offset < 850) {
    heroImage.style.transform =
      `scale(1.03) translateY(${offset * 0.035}px)`;
  }
});

/* MAP SIZE FIX */

window.addEventListener("load", () => {
  setTimeout(() => {
    malangMap.invalidateSize(true);
  }, 350);
});

window.addEventListener("resize", () => {
  setTimeout(() => {
    malangMap.invalidateSize(true);
  }, 180);
});

/* INITIAL */

applyFilters();

